/** Grade and class labels stored in Arabic, shown in English when that language is on. */
function placeLabel(text) {
	if (!text) return text;
	if (activeLocale !== "en") return text;
	const exact = EN_UI[text];
	if (exact) return exact;
	if (SHORT_GRADE[text]) return SHORT_GRADE[text];
	let out = text;
	const ordered = [...GRADE_PHRASES].sort((a, b) => b[0].length - a[0].length);
	for (const [ar, en] of ordered) if (out.includes(ar)) out = out.split(ar).join(en);
	out = out.replace(/الأولى|الاولى|أولى|اولى/g, "First").replace(/الثاني|ثاني/g, "Second").replace(/الثالث|ثالث/g, "Third");
	return out;
}
